a2a:agent-card.a2a:json:
{
  "name": "Output Quality Demo Agent",
  "description": "Answers questions with a real model, or with scripted misbehaving answers (biased, toxic, hallucinated, off-topic, prompt leak, looping) to demonstrate the Output Quality & Anomaly Detection policy.",
  "version": "1.1.0",
  "protocolVersion": "1.0",
  "supportedInterfaces": [
    { "protocolBinding": "JSONRPC", "url": "${agent.publicUrl}${agent.path}/jsonrpc", "protocolVersion": "1.0" }
  ],
  "capabilities": { "streaming": false, "pushNotifications": false, "extendedAgentCard": false },
  "defaultInputModes": ["text/plain"],
  "defaultOutputModes": ["text/plain"],
  "skills": [
    {
      "id": "answer-question",
      "name": "Answer_Question",
      "description": "Answers a general question. Set message.metadata.demo_mode to bias, toxic, hallucinate, quoted, offtopic, leak, loop or empty for a scripted answer, or to a mode with metadata.answer_source=model for a real model prompted to misbehave.",
      "tags": ["demo", "output-quality", "llm"]
    }
  ]
}

a2a:update-task-artifact.a2a:artifact-content:
#[%dw 2.0
output application/json
---
{
  artifactUpdate: {
    taskId: vars.taskId,
    contextId: vars.contextId,
    artifact: { artifactId: "answer-" ++ vars.taskId, name: "answer", parts: [{ text: vars.answer }] }
  }
}]

a2a:update-task-status.a2a:status-content:
#[%dw 2.0
output application/json
---
// The connector requires a non-empty status message; the answer itself is the artifact.
{ statusUpdate: { taskId: vars.taskId, contextId: vars.contextId, status: {
    state: "TASK_STATE_COMPLETED",
    message: { messageId: uuid(), role: "ROLE_AGENT", parts: [{ text: "Answer ready." }] }
} } }]

#[%dw 2.0
output application/json
---
{ statusUpdate: { taskId: vars.taskId, contextId: vars.contextId, status: {
    state: "TASK_STATE_FAILED",
    message: { messageId: uuid(), role: "ROLE_AGENT", parts: [{ text: "The agent could not answer: " ++ (error.errorType.identifier default "UNKNOWN") }] }
} } }]
